fn sort(v: Vec<Int>) -> Vec<Int> {
    let mut v = v;
    for i in 0..v.len() {
        for j in i+1..v.len() {
            if v[i] > v[j] {
                let temp = v[i];
                v[i] = v[j];
                v[j] = temp;
            }
        }
    }
    v
}

